from pathlib import Path
import hashlib,json
H=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def load(p):return json.loads(p.read_text(encoding='utf-8-sig'))
w=load(H/'witness.json');v=load(H/'verification.json')
assert v['witnessSha256']==sha(H/'witness.json') and v['checks']==1206
lines=['# Gezielte Retail-Probe: ORIGIN und SCD','','Die Probe ist abgeschlossen. Zwölf Archiveinträge ergeben drei gespeicherte ORIGIN-Wrapper und 13 SCD-Instanzen mit elf unterschiedlichen Hashes. Alle zwölf Original-Payloads und drei Audio-Remaster stimmen vollständig mit den bereits vorhandenen entpackten Dateien überein. Es wurden keine Spiel- oder Audiodaten exportiert.','','## Stichprobe','','| Auswahl | Version | Bank-ID | Sequenzen | Tabelle B / C | Physisch minus deklariert |','|---|---:|---:|---:|---:|---:|']
seen=set()
for s in v['samples']:
 if s['sha256'] in seen:continue
 seen.add(s['sha256']);label=s['asset'].split('.hed/')[-1]
 lines.append(f"| {label} | {s['version']} | {s['bankId']} | {s['sequences']} | {s['tableB']} / {s['tableC']} | {s['physicalMinusDeclared']} |")
lines+=['','Die zusätzlichen Exemplare von se000 und se999 in kh2_first und kh2_sixth sind bytegleich. Daraus folgt keine Aussage zur Ladepriorität. Längenabweichungen werden als Messwerte erfasst und nicht pauschal als Fehler gewertet.','','## Gespeicherte Wrapper','','- obj/M_EX950.a.us: Typ31, se/obj/se271, genau ein gleichnamiger SCD-Remaster.','- obj/B_EX120.a.us: Typ31 se/obj/se265 und Typ34 voice/battle/us/n_dancer; beide haben genau einen gleichnamigen SCD-Remaster.','- Alle drei Wrapper sind 48 Byte lang. Das Namensfeld beginnt bei +16. Beim Voice-Wrapper reicht es bis in die späteren Runtimefelder hinein; die Diskbytes bei +32/+40 sind daher keine Runtimepointer.','','In sämtlichen 13 erfassten SCD-Instanzen steht Byte15 jedes hier gelesenen Sequenzheaders auf null. Das ist ein Dateibefund. Er belegt keine ausgeführte native Mutation und keinen Spielzustand.','','## Methode und Grenzen','','Die isolierte Console verlinkt vier unveränderte Core-Dateien des AssetArchiveReader. Sie öffnet Quellen nur lesend, dekodiert ausschließlich die zwölf gezielt ausgewählten Package-Records in Arbeitsspeicher und speichert Headerfelder, IDs, Tabellenstatistiken, Längen und Hashes. Textur-Remaster werden in der finalen Probe nicht dekodiert. Kleine HED-Indizes werden vollständig gelesen; die großen PKGs werden nur an den ausgewählten Records gelesen.','', 'Die unabhängige Python-Nachprüfung besteht mit 1.206 Checks. Sie prüft Original-HED-Zeilen, Record-Header, gespeicherte Record-Hashes, Loose-Dateihashes, 52 Tabellenstatistiken und alle ausgegebenen Sequenzfelder erneut. Sie ist kein zweiter unabhängiger Package-Decoder. Die vollständige Archiv-/Loose-Bytegleichheit liefert der unveränderte Produktreader.','', 'Für Tabelle B und C wird am Ziel nur die Ein-Byte-Schranke geprüft; vollständige Objektlängen bleiben unbekannt. Sequenzheader werden für Version3 mit 16 und für Version4 mit 32 Byte geprüft; Aux-Einträge mit 128 Byte. Physische und deklarierte Schranken bleiben getrennt. Kein Codec, kein Trackbytecode und keine Wiedergabe werden ausgeführt oder als gültig bestätigt.','', 'Die Feldzuordnung folgt dem bereits erfassten 09FBD0-/09FD20-Pfad der ORIGIN-Studie und der parallelen Formatprüfung. Diese Retail-Probe selbst ist kein neuer IDA-Funktionscapture.','', 'inventory.json und InventoryProbe.cs.txt halten die vorausgehende kleine Auswahlprobe fest, einschließlich des negativen P_EX100.a.us-Falls. inspect_loose_bar.py prüft zusätzlich nur die BAR-Metadaten von fünf benannten Dateien. Diese Vorprobe ist nicht Teil der zwölf finalen Records.','', '## Reproduktion','','```powershell','dotnet run --project artifacts/audio-retail-witness-20261011/Probe.csproj -- <Spielordner> <absoluter-Pfad-im-Probeordner>/witness.json','py -3 -B artifacts/audio-retail-witness-20261011/verify.py --check','```','','Buildausgaben der isolierten Console liegen nur in ihrem lokalen bin/obj. Sie sind nicht Teil des Metadatenmanifests. Produktquellen, docs, build und Paket bleiben unverändert.']
(H/'report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
provenance={'status':'BOUNDED_READ_ONLY_RETAIL_WITNESS','selectedArchiveRecords':12,'distinctSelectedAssetNames':10,'SCDInstances':13,'uniqueSCDHashes':11,'ORIGINWrappers':3,'fullByteComparisons':15,'metadataChecks':1206,'originalGameWrites':False,'payloadExports':False,'gameExecution':False,'productChanges':False,'linkedSourcePins':w['linkedSourcePins'],'witnessSha256':sha(H/'witness.json'),'verificationSha256':sha(H/'verification.json'),'rawDataPolicy':'Only metadata/hashes are persisted. Full selected bytes are read transiently in memory.','existingLooseRoot':'E:/SteamLibrary/steamapps/common/KINGDOM HEARTS -HD 1.5+2.5 ReMIX-/Modding/openkh/data/kh2','fieldBasis':'Accepted ORIGIN 09FBD0/09FD20 original-byte bodies; independently re-read disk bytes; no new IDA capture.','excluded':['bin/','obj/'],'preliminaryArtifacts':['inventory.json','InventoryProbe.cs.txt','inspect_loose_bar.py']}
(H/'provenance.json').write_text(json.dumps(provenance,indent=2)+'\n')
manifest={'schema':1,'scope':'Metadata-only targeted retail witness; generated Console bin/obj excluded.','files':{p.name:{'bytes':p.stat().st_size,'sha256':sha(p)} for p in sorted(H.iterdir()) if p.is_file() and p.name!='manifest.json'}}
(H/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(json.dumps({'manifestSha256':sha(H/'manifest.json'),'witnessSha256':sha(H/'witness.json'),'files':len(manifest['files'])}))
